/*
 * prog44_miller_rabin – deterministic Miller‑Rabin primality test
 *
 * Behaviour (exactly as observed in the original binary):
 *
 *   * No command‑line argument          → prints "NO_INPUT"
 *   * Argument not a valid decimal     → prints "BAD_INPUT"
 *   * Value > 0xBFA17DC6 (≈3.2·10⁹)    → prints "OUT_OF_RANGE"
 *   * Otherwise runs a deterministic Miller‑Rabin test
 *       using the bases {2,3,5,7,11,13}.  For the range
 *       up to 0xBFA17DC6 this set is provably sufficient.
 *       * Prime   → prints "PRIME"
 *       * Composite → prints "NOT_PRIME"
 *
 * The program is deliberately small and reproduces the exact
 * observable output of the original (obfuscated) binary.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <inttypes.h>
#include <errno.h>

/* -------------------------------------------------------------
 * Deterministic Miller‑Rabin for 32‑bit numbers.
 * Uses the bases 2,3,5,7,11,13 which are sufficient for all
 * n < 0xBFA17DC6 (the limit used by the original program).
 * ------------------------------------------------------------- */
static int is_prime_uint32(uint32_t n)
{
    /* Small numbers and trivial divisibility checks */
    if (n < 2)               return 0;
    static const uint32_t bases[] = {2, 3, 5, 7, 11, 13};
    for (size_t i = 0; i < 6; ++i) {
        if (n == bases[i])   return 1;          /* n is one of the bases */
        if (n % bases[i] == 0) return 0;        /* divisible by a small prime */
    }

    /* Write n‑1 = d·2^s with d odd */
    uint32_t d = n - 1;
    int      s = 0;
    while ((d & 1U) == 0) {
        d >>= 1;
        ++s;
    }

    /* Miller‑Rabin test for each base */
    for (size_t i = 0; i < 6; ++i) {
        uint64_t a = bases[i];
        uint64_t x = 1;
        uint64_t cur = a % n;
        uint32_t e = d;

        /* x = a^d (mod n) – binary exponentiation */
        while (e) {
            if (e & 1U) x = (x * cur) % n;
            cur = (cur * cur) % n;
            e >>= 1;
        }

        if (x == 1 || x == n - 1) continue;

        int r;
        for (r = 1; r < s; ++r) {
            x = (x * x) % n;
            if (x == n - 1) break;
        }
        if (r == s) return 0;   /* composite */
    }
    return 1;                    /* prime (deterministic for this range) */
}

/* -------------------------------------------------------------
 * Main program – reproduces the exact output strings of the
 * original binary.
 * ------------------------------------------------------------- */
int main(int argc, char *argv[])
{
    /* 1. Argument count */
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }

    /* 2. Convert the argument to a number */
    char *endptr = NULL;
    errno = 0;
    long long val = strtoll(argv[1], &endptr, 10);

    /* 3. Detect bad input (no digits, extra characters, overflow) */
    if (endptr == argv[1] || *endptr != '\0' || errno == ERANGE) {
        puts("BAD_INPUT");
        return 0;
    }

    /* 4. Range check – the original program limited the value */
    const uint64_t MAX_VAL = 0xBFA17DC6ULL;   /* 3 200 000 006 decimal */
    if ((uint64_t)val > MAX_VAL) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    /* 5. Perform the primality test */
    uint32_t n = (uint32_t)val;
    if (is_prime_uint32(n))
        puts("PRIME");
    else
        puts("NOT_PRIME");

    return 0;
}
